/* Eventos con boletos · catálogo de plantillas (ES/EN). SOLO SANDBOX. Todo ficticio: artistas, lugares y precios inventados.
   Una plantilla = un tipo de evento; el plan (plan.mjs) la reparte entre los negocios que le quedan bien, en las 5 ciudades.
   Forma de los boletos, mesas y extras = la de tickets_cfg / tables_cfg / addons_cfg de 0035 (evt_sincronizar_venta los vuelve filas).
   Reglas de la base que se respetan aquí: título ≤ 70, boleto ≤ 40 + nota ≤ 80, descripción ≤ 400, extras sin alcohol (evt_extras_ok),
   mesas ≤ 12, boletos ≤ 16, «antes de ir» ≤ 6, un evento de varios días sin mesas, hasta 12 h de duración. */

const B = (es, en) => ({ es, en: en ?? es });
/* tk(id, nombre, en, nota, nota en, dólares, cantidad, extra) */
export const tk = (id, es, en, ses, sen, usd, cap, x = {}) => ({ id, n: B(es, en), s: B(ses, sen), p: Math.round(usd * 100), cap, off: false, ...x });
export const mesa = (id, es, en, seats, minUsd, depUsd, cap) => ({ id, z: B(es, en), seats, min: Math.round(minUsd * 100), dep: Math.round(depUsd * 100), cap });
export const extra = (id, es, en, ses, sen, usd, kind, soloMesa = false) => ({ id, n: B(es, en), s: B(ses, sen), p: Math.round(usd * 100), kind, mesa: soloMesa });
const lu = (h, who, es, en) => ({ h, who, role: B(es, en ?? es) });

